//! Real process boundaries prove durable state is shared across CLI restarts.
//! Every root here is disposable and generated by tempfile.
use serde_json::Value;
use std::fs;
use std::path::Path;
use std::process::{Command, Output};

fn run(state: &Path, args: &[&str]) -> Output {
    Command::new(env!("CARGO_BIN_EXE_devdrop"))
        .args(["local", "--state-dir"])
        .arg(state)
        .args(args)
        .output()
        .expect("start CLI")
}
fn successful(state: &Path, args: &[&str]) -> Value {
    let output = run(state, args);
    assert!(
        output.status.success(),
        "CLI refused: {}",
        String::from_utf8_lossy(&output.stderr)
    );
    serde_json::from_slice(&output.stdout).expect("JSON response")
}

#[test]
fn separate_process_registration_preview_approval_and_restore() {
    let temp = tempfile::tempdir().unwrap();
    let source = fs::canonicalize(temp.path()).unwrap().join("source");
    let target = fs::canonicalize(temp.path()).unwrap().join("target");
    let state = fs::canonicalize(temp.path()).unwrap().join("state");
    fs::create_dir(&source).unwrap();
    fs::create_dir(&target).unwrap();
    fs::write(source.join("hello.txt"), b"hello fixture").unwrap();
    fs::write(source.join(".env"), b"TOKEN=DO_NOT_LEAK").unwrap();
    let registered = successful(
        &state,
        &[
            "register",
            "Disposable test",
            source.to_str().unwrap(),
            target.to_str().unwrap(),
        ],
    );
    let pair_id = registered["id"].as_str().expect("pair id");
    let listed = successful(&state, &["list"]);
    assert_eq!(listed["pairs"][0]["id"], pair_id);
    let preview = successful(&state, &["preview", pair_id]);
    let plan_id = preview["id"].as_str().expect("plan id");
    assert!(!target.join("hello.txt").exists());
    assert!(!preview.to_string().contains("DO_NOT_LEAK"));
    let refused = run(&state, &["apply", plan_id, "--approve", "wrong-plan"]);
    assert!(!refused.status.success());
    assert!(!target.join("hello.txt").exists());
    successful(&state, &["apply", plan_id, "--approve", plan_id]);
    assert_eq!(
        fs::read(target.join("hello.txt")).unwrap(),
        b"hello fixture"
    );
    assert!(!target.join(".env").exists());
    // Repeated approval must never duplicate a mutation or lose the receipt.
    let _ = run(&state, &["apply", plan_id, "--approve", plan_id]);
    assert_eq!(
        fs::read(target.join("hello.txt")).unwrap(),
        b"hello fixture"
    );
    let undo = successful(&state, &["rollback-preview", plan_id]);
    let undo_id = undo["id"].as_str().expect("undo plan id");
    assert!(target.join("hello.txt").exists());
    successful(&state, &["apply", undo_id, "--approve", undo_id]);
    assert!(!target.join("hello.txt").exists());
    assert!(!successful(&state, &["events"])
        .to_string()
        .contains("DO_NOT_LEAK"));
}

#[test]
fn stale_preview_cannot_overwrite_a_new_target_edit() {
    let temp = tempfile::tempdir().unwrap();
    let source = fs::canonicalize(temp.path()).unwrap().join("source");
    let target = fs::canonicalize(temp.path()).unwrap().join("target");
    let state = fs::canonicalize(temp.path()).unwrap().join("state");
    fs::create_dir(&source).unwrap();
    fs::create_dir(&target).unwrap();
    fs::write(source.join("code.txt"), b"incoming").unwrap();
    let pair = successful(
        &state,
        &[
            "register",
            "Stale test",
            source.to_str().unwrap(),
            target.to_str().unwrap(),
        ],
    );
    let plan = successful(&state, &["preview", pair["id"].as_str().unwrap()]);
    fs::write(target.join("code.txt"), b"local edit").unwrap();
    let id = plan["id"].as_str().unwrap();
    assert!(!run(&state, &["apply", id, "--approve", id])
        .status
        .success());
    assert_eq!(fs::read(target.join("code.txt")).unwrap(), b"local edit");
}
